    {'cat': 'greet', 'text': "Bonsoir. La nuit est belle, malgré l'orage. Comme certaines personnes.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_mei_gown_greet_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Je suis ravie. Sincèrement, ce qui est rare dans un salon.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_mei_gown_greet_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Puis-je vous poser une question indiscrète ? Plus tard, peut-être.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_mei_gown_greet_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet', 'text': 'Bonsoir. Vous êtes ici pour danser, ou pour regarder les autres ?', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'warm', 'line_id': 'L_mei_gown_greet_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': "Vous revenez. Je l'avais deviné.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_again_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Encore une conversation ? Avec plaisir. Et prudence.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_again_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'greet_again', 'text': 'Votre persévérance est une qualité. Ou un indice.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_again_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'shout', 'text': "Un coup de feu ! Mettez-vous à l'abri !", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_mei_gown_shout_gun_01', 'whispered': False, 'nonverbal': False, 'gun': True, 'cause': 'gun'},
