    {'cat': 'shout', 'text': 'Le feu ! Par ici, la sortie est dégagée !', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_mei_gown_shout_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'fire'},
