    {'cat': 'shout', 'text': 'Une explosion ! Restez à terre !', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_mei_gown_shout_explosion_01', 'whispered': False, 'nonverbal': False, 'gun': False, 'cause': 'explosion'},
